#!/usr/bin/env python3
import numpy as np, os, json, sys


def load_data():
    path = os.getenv('STANFORD_ENTANGLEMENT_PATH')
    if path and os.path.isfile(path):
        try:
            with open(path, 'r') as f:
                data = json.load(f)
            times = np.array(data.get('times', []))
            vals = np.array(data.get('values', []))
            if len(times) == len(vals):
                return times, vals
        except Exception as e:
            print(f"Failed to read Stanford file: {e}")
    # fallback synthetic data
    np.random.seed(0)
    t = np.linspace(0, 10, 1000)
    y = np.sin(2*np.pi*t) * (1 + 0.2*np.random.randn(t.size))
    return t, y


def compute_rms_error(t, y, model_func):
    residuals = y - model_func(t)
    return np.sqrt(np.mean(residuals**2))


def main():
    t, y = load_data()
    # simple linear model for illustration
    def model(t):
        return 0.5 * t
    rms = compute_rms_error(t, y, model)
    print(f"RMS error of linear model: {rms:.6f}")

if __name__ == "__main__":
    main()

