#!/usr/bin/env python3
import math, random, statistics

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
hbar = 1.054571817e-34  # J s
k_B = 1.380649e-23      # J K^-1
M_sun = 1.98847e30      # kg

def schwarzschild_radius(M):
    return 2 * G * M / c**2

def isco_radius(M):
    # Prograde ISCO for a non-rotating BH (a=0) from Bardeen et al.
    return 6 * G * M / c**2

def horizon_area(r):
    return 4 * math.pi * r**2

def hawking_temperature(M):
    return hbar * c**3 / (8 * math.pi * G * M * k_B)

def planck_length():
    return math.sqrt(hbar * G / c**3)

def bh_entropy(r):
    # S = k_B * A / (4 * l_P^2)
    l_p2 = planck_length()**2
    return k_B * horizon_area(r) / (4 * l_p2)

def random_bh_mass():
    # Log-uniform between 1e30 kg (≈ 0.5 M_sun) and 1e32 kg (≈ 500 M_sun)
    log_min = math.log10(1e30)
    log_max = math.log10(1e32)
    return 10 ** random.uniform(log_min, log_max)

def run_trials(trials=1000):
    results = []
    for i in range(trials):
        M = random_bh_mass()
        r_s = schwarzschild_radius(M)
        r_isco = isco_radius(M)
        T = hawking_temperature(M)
        l_p = planck_length()
        A = horizon_area(r_s)
        S = bh_entropy(r_s)
        results.append({
            "trial": i,
            "mass_kg": M,
            "r_s_m": r_s,
            "r_isco_m": r_isco,
            "temperature_K": T,
            "planck_length_m": l_p,
            "horizon_area_m2": A,
            "entropy_J_per_K": S
        })
    return results

if __name__ == "__main__":
    data = run_trials()
    # Simple sanity check output
    for entry in data[:5]:
        print(entry)

